// One lead per request. The site posts multipart/form-data: text fields
// arrive in `body`, the logo (if any) as binary data.
const MARKETS = {
  'pt-PT': { name: 'Portugal', subject: 'Recebemos o seu pedido — RUPE', hello: 'Olá', body: 'Recebemos o seu pedido. Vamos criar o seu site e mostrar-lho em breve: se gostar, paga, e fica publicado em 2 dias.', sign: 'Até já,<br>RUPE' },
  'pt-BR': { name: 'Brasil', subject: 'Recebemos seu pedido — RUPE', hello: 'Olá', body: 'Recebemos seu pedido. Vamos criar seu site e te mostrar em breve: se você gostar, paga, e ele fica no ar em 2 dias.', sign: 'Até logo,<br>RUPE' },
  'en-US': { name: 'EUA', subject: 'We got your request — RUPE', hello: 'Hi', body: 'We got your request. We will build your site and show it to you soon: if you love it, you pay, and it goes live in 2 days.', sign: 'Talk soon,<br>RUPE' },
};

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? {};
  // Honeypot: a field people never see. Filled in means a bot — drop it.
  if (b.website) continue;
  if (!b.email || !b.name) continue;

  const m = MARKETS[b.market] ?? MARKETS['pt-PT'];
  const colors = String(b.colors ?? '').split(',').map((c) => c.trim()).filter((c) => /^#[0-9a-f]{3,8}$/i.test(c));
  const swatches = colors
    .map((c) => `<span style="display:inline-block;width:22px;height:22px;border-radius:50%;background:${c};border:1px solid #ccc;vertical-align:middle;margin-right:6px"></span>${c}`)
    .join('<br>');

  const rows = [
    ['Mercado', esc(m.name)],
    ['Nome', esc(b.name)],
    ['Email', `<a href="mailto:${esc(b.email)}">${esc(b.email)}</a>`],
    ['Telefone', esc(b.phone) || '—'],
    ['Negócio', esc(b.business) || '—'],
    ['O que precisa', esc(b.type) || '—'],
    ['Projeto', esc(b.brief).replace(/\n/g, '<br>') || '—'],
    ['Cores', swatches || '—'],
    ['Cores (descrição)', esc(b.colorsNote) || '—'],
    ['Logótipo', item.binary && Object.keys(item.binary).length ? 'em anexo' : '—'],
    ['Referência', esc(b.reference) || '—'],
    ['Página', esc(b.page)],
  ];

  const html = `<div style="font-family:-apple-system,Segoe UI,sans-serif;color:#111"><h2 style="margin:0 0 12px">Novo pedido · ${esc(m.name)}</h2><table cellpadding="8" style="border-collapse:collapse">${rows
    .map(([k, v]) => `<tr><td style="color:#666;vertical-align:top;white-space:nowrap"><b>${k}</b></td><td>${v}</td></tr>`)
    .join('')}</table></div>`;

  const confirmation = `<div style="font-family:-apple-system,Segoe UI,sans-serif;color:#111;line-height:1.6"><p>${m.hello} ${esc(b.name)},</p><p>${m.body}</p><p>${m.sign}</p></div>`;

  out.push({
    json: {
      ...b,
      marketName: m.name,
      subject: `Novo lead (${m.name}) · ${b.name} · ${b.type ?? ''}`,
      html,
      confirmSubject: m.subject,
      confirmHtml: confirmation,
    },
    binary: item.binary,
  });
}
return out;
